try{$effective=chr_assignment($pdo,$id,date('Y-m-d'));}catch(InvalidArgumentException $e){$effective=null;echo '<div class="alert error">'.h($e->getMessage()).'</div>';}
?><section class="card"><h2>Attendance & Shift</h2><p>Current effective shift: <strong><?=h($effective['title']??'Unassigned')?></strong> · Source: <?=h($effective['assignment_source']??'None')?></p><?php if(can($pdo,$user,'shifts.manage')):?><form method="post" class="form-grid core-form"><?php ftoken();?><input type="hidden" name="action" value="core_config"><input type="hidden" name="module" value="roster"><input type="hidden" name="employee_id" value="<?=$id?>"><input type="hidden" name="title" value="Employee shift override"><input type="hidden" name="active" value="1"><label>Assign different shift<select name="shift_id" required><option value="">Select shift</option><?php foreach(chr_rows($pdo,'shifts') as $s)if($s['status']==='Active'):?><option value="<?=(int)$s['id']?>"><?=h($s['title'])?></option><?php endif;?></select></label><?php field('from','Effective from',['from'=>date('Y-m-d')],'date',true);field('to','Effective to (optional)',[],'date');field('notes','Reason',[],'text',true,2000);?><div class="full"><button class="button primary">Assign individual override</button> <a class="button" href="?page=roster">Manage assignment end dates</a></div></form><?php endif;?><div class="table-scroll"><table class="directory"><thead><tr><th>Shift</th><th>Type</th><th>From</th><th>To</th><th>Created</th><th>Status</th></tr></thead><tbody><?php foreach(chr_rows($pdo,'roster') as $r)if((int)$r['employee_id']===$id):$d=$r['values'];$s=chr_record($pdo,'shifts',(int)$d['shift_id']);?><tr><td><?=h($s['title']??'Unavailable')?></td><td>Employee</td><td><?=h($d['from'])?></td><td><?=h($d['to']??'Ongoing')?></td><td><?=h($r['created_at'])?></td><td><?=h($r['status'])?></td></tr><?php endif;?></tbody></table></div></section>
